content:
{
  "code": ":root {
  --color-ivory: #F9F7F2;
  --color-terracotta: #C0583B;
  --color-terracotta-hover: #A3462D;
  --color-charcoal: #2C2C2C;
  --color-text-secondary: #595959;
  --color-border: #E0DCD5;
  --color-bg-white: #FFFFFF;

  --font-family-base: "Noto Sans KR", sans-serif;
  --font-weight-regular: 500;
  --font-weight-bold: 700;

  --spacing-xs: 8px;
  --spacing-sm: 12px;
  --spacing-md: 24px;
  --spacing-lg: 48px;
  --spacing-xl: 64px;

  --max-width-desktop: 1120px;
  --border-radius-card: 8px;
  --transition-base: 0.2s ease;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  font-family: var(--font-family-base);
  font-weight: var(--font-weight-regular);
  font-size: 16px;
  line-height: 1.5;
  color: var(--color-charcoal);
  background-color: var(--color-ivory);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1,
h2,
h3 {
  margin: 0;
  font-weight: var(--font-weight-bold);
  color: var(--color-charcoal);
}

p {
  margin: 0;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  padding: 0;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.masthead {
  padding: var(--spacing-lg) var(--spacing-md);
  text-align: center;
  background-color: var(--color-bg-white);
}

.masthead h1 {
  font-size: 28px;
  letter-spacing: -0.02em;
  margin-bottom: var(--spacing-xs);
}

.subtitle {
  font-size: 14px;
  color: var(--color-text-secondary);
}

.editorial-hero {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--spacing-xl) var(--spacing-md);
  gap: var(--spacing-lg);
  max-width: var(--max-width-desktop);
  margin: 0 auto;
}

.pottery-illustration {
  flex: 1;
  max-width: 400px;
  height: 320px;
  background-color: #E8E2D9;
  border-radius: var(--border-radius-card);
  position: relative;
  overflow: hidden;
}

.pottery-illustration::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 120px;
  height: 140px;
  border: 8px solid var(--color-terracotta);
  border-radius: 50%;
}

.pottery-illustration::after {
  content: "";
  position: absolute;
  bottom: 40px;
  left: 50%;
  transform: translateX(-50%);
  width: 160px;
  height: 24px;
  background-color: var(--color-terracotta);
  border-radius: 12px;
  opacity: 0.8;
}

.hero-content {
  flex: 1;
  max-width: 480px;
}

.hero-content h2 {
  font-size: 36px;
  line-height: 1.2;
  margin-bottom: var(--spacing-md);
  letter-spacing: -0.01em;
}

.hero-content p {
  font-size: 18px;
  color: var(--color-text-secondary);
  line-height: 1.6;
}

.search-section {
  max-width: var(--max-width-desktop);
  margin: 0 auto var(--spacing-lg) auto;
  padding: 0 var(--spacing-md);
}

#search {
  width: 100%;
  padding: var(--spacing-sm) var(--spacing-md);
  font-size: 16px;
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius-card);
  background-color: var(--color-bg-white);
  color: var(--color-charcoal);
}

#search:focus {
  outline: none;
  border-color: var(--color-terracotta);
  box-shadow: 0 0 0 2px rgba(192, 88, 59, 0.2);
}

#catalogue-list {
  max-width: var(--max-width-desktop);
  margin: 0 auto;
  padding: 0 var(--spacing-md);
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-lg);
}

.catalogue-card {
  background-color: var(--color-bg-white);
  border-radius: var(--border-radius-card);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.catalogue-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.06);
}

.card-illustration {
  height: 180px;
  background-color: #EAE5DC;
  width: 100%;
}

.catalogue-card h3 {
  font-size: 20px;
  padding: var(--spacing-md) var(--spacing-md) var(--spacing-xs);
}

.card-category {
  display: block;
  padding: 0 var(--spacing-md) var(--spacing-sm);
  font-size: 14px;
  color: var(--color-terracotta);
  font-weight: var(--font-weight-bold);
}

.card-description {
  padding: 0 var(--spacing-md) var(--spacing-sm);
  font-size: 15px;
  color: var(--color-text-secondary);
  flex-grow: 1;
}

.card-meta {
  padding: 0 var(--spacing-md) var(--spacing-sm);
  display: flex;
  gap: var(--spacing-md);
  font-size: 14px;
  color: var(--color-text-secondary);
}

.card-price {
  padding: 0 var(--spacing-md) var(--spacing-sm);
  font-size: 18px;
  font-weight: var(--font-weight-bold);
  color: var(--color-charcoal);
}

.btn-detail {
  margin: var(--spacing-sm) var(--spacing-md) var(--spacing-md);
  padding: var(--spacing-sm) 0;
  background-color: var(--color-charcoal);
  color: var(--color-bg-white);
  text-align: center;
  border-radius: 4px;
  font-weight: var(--font-weight-bold);
  transition: background-color var(--transition-base);
}

.btn-detail:hover {
  background-color: var(--color-terracotta);
}

.btn-detail:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--color-bg-white), 0 0 0 4px var(--color-terracotta);
}

